// Postfach-Zugang aus der Oberfläche. Herkunft prüfen wie bei ALLY 8, Sitzung aus dem Cookie.
// Das Passwort geht nur an die n8n-Zugangsdaten, nie in die Datenbank. Dieser Ablauf speichert keine Ausführungsdaten.
// Eigene Adresse aus der Anfrage (Host-Kopfzeile, von traefik unverändert weitergegeben). n8n ist nur über traefik erreichbar,
// traefik leitet nur eingerichtete Adressen weiter. So gelten die bisherige n8n-Adresse und die eigene Adresse der Oberfläche ohne feste Werte (17.10.2026).
// Migration 88 (Stefan 22.10.2026, 16:55): dieselbe Eingabe gilt für Lesen (IMAP) und Versand (SMTP). Nur mit „Andere Daten für den Versand“ (smtp_anders)
// eigener Server, Port, Benutzer und Passwort für den Versand (leeres Passwort = dasselbe wie für das Lesen). Passwörter nie in "daten", nur ihre Länge.
// Migration 90 (Stefan 22.10.2026): art = persoenlich für ein neues persönliches Postfach (Mein Konto › Meine Postfächer), sonst gemeinsam; Rechte prüft die Datenbank.
const HOST = (x => /^[a-z0-9.-]{1,253}$/.test(x) ? 'https://' + x : '')(String(($json.headers || {}).host || '').trim().toLowerCase());
const h = $json.headers || {};
const b = $json.body || {};
const herkunft = String(h.origin || '');
const verweis = String(h.referer || '');
// Verweis nur mit Trennzeichen nach dem Seitenpfad (Ende, '/', '?' oder '#'), sonst gälte auch /webhook/web-xyz (Stefan 17.10.2026)
const SEITE_PFAD = HOST + '/webhook/web';
const vonSeite = verweis.startsWith(SEITE_PFAD) && (verweis.length === SEITE_PFAD.length || '/?#'.includes(verweis[SEITE_PFAD.length]));
const herkunftOk = HOST !== '' && (herkunft === HOST || ((herkunft === '' || herkunft === 'null') && vonSeite));
const kekse = String(h.cookie || '').split(';').map(x => x.trim());
const roh = (kekse.find(x => x.startsWith('ally_sitzung=')) || '').slice('ally_sitzung='.length);
const token = /^[0-9a-f]{64}$/.test(roh) ? roh : '';
const s = v => String(v ?? '').trim();
const aktion = herkunftOk && ['zugang_speichern', 'zugang_pruefen', 'platz_freigeben'].includes(s(b.aktion)) ? s(b.aktion) : 'ungueltig';
const platz = /^[0-9]{1,9}$/.test(s(b.platz)) ? Number(s(b.platz)) : 0;  // Migration 173 (Schritt P, P3): Nummer ohne Grenze (0 = neues Postfach)
const pw = String(b.passwort ?? '');
const anders = s(b.smtp_anders) === '1';
const pwV = anders ? String(b.smtp_passwort ?? '') : '';
const daten = {
  host: s(b.host).toLowerCase(), port: s(b.port), benutzer: s(b.benutzer), ssl: b.ssl ? '1' : '',
  adresse: s(b.adresse).toLowerCase(), name: s(b.name), passwort_laenge: String(pw.length),
  smtp_anders: anders ? '1' : '', smtp_host: anders ? s(b.smtp_host).toLowerCase() : '', smtp_port: anders ? s(b.smtp_port) : '', smtp_benutzer: anders ? s(b.smtp_benutzer) : '',
  smtp_passwort_laenge: String(pwV.length), art: s(b.art) === 'persoenlich' ? 'persoenlich' : ''
};
return [{ json: { token, aktion, platz, daten: JSON.stringify(daten), pw, pw_versand: pwV.length ? pwV : pw } }];

// Antworten der n8n-Schnittstelle zusammenfassen (ohne Passwort)
// Migration 88 (Stefan 22.10.2026, 16:55): zusätzlich der Versand (SMTP) des Platzes – gesetzt und geprüft mit derselben Eingabe bzw. beim Prüfen mitgeprüft
const F = $('Formular prüfen').first().json;
const V = $('Vorbereiten').first().json.v || {};
const lauf = n => $(n).isExecuted ? ($(n).first() || {}).json || {} : null;
const meldung = r => r ? String(((r.body || {}).message) || (r.body && r.body.status) || ('Status ' + r.statusCode)).slice(0, 300) : '';
const setzen = lauf('Zugangsdaten setzen') || lauf('Zugangsdaten leeren') || lauf('IMAP anlegen');
const test = lauf('Verbindung prüfen (nach Speichern)') || lauf('Verbindung prüfen') || lauf('IMAP prüfen (neu)');
const stand = lauf('Empfang nachsehen') || lauf('Empfang nachsehen (Freigeben)') || lauf('Workflow nachsehen');
const api = {};
if (setzen) { api.patch_status = String(setzen.statusCode); if (setzen.statusCode !== 200) api.patch_meldung = meldung(setzen); }
if (test) { api.test_status = (test.body || {}).status === 'OK' ? 'OK' : 'Error'; api.test_meldung = (test.body || {}).status === 'OK' ? '' : String((test.body || {}).message || ('Status ' + test.statusCode)).slice(0, 300); }
const vSetzen = lauf('Versand-Zugangsdaten setzen') || lauf('SMTP anlegen');
const vTest = lauf('Versand prüfen (nach Speichern)') || lauf('Versand prüfen') || lauf('SMTP prüfen (neu)');
const fehlerText = r => r.error ? String(r.error.message || r.error.description || r.error).slice(0, 300) : meldung(r);
if (vSetzen) { api.versand_patch_status = String(vSetzen.statusCode || ''); if (vSetzen.statusCode !== 200) api.versand_patch_meldung = fehlerText(vSetzen); }
if (vTest) { const ok = !vTest.error && (vTest.body || {}).status === 'OK'; api.versand_test_status = ok ? 'OK' : 'Error'; api.versand_test_meldung = ok ? '' : String(((vTest.body || {}).message) || fehlerText(vTest)).slice(0, 300); }
if (stand) {
  const aktiv = stand.statusCode === 200 && stand.body && stand.body.active === true;
  const soll = F.aktion === 'zugang_speichern' && api.test_status === 'OK';
  if (stand.statusCode !== 200) { api.schalt_status = 'fehler'; api.schalt_meldung = meldung(stand); }
  else if (aktiv === soll) api.schalt_status = aktiv ? 'ein' : 'aus';
  else { api.schalt_status = 'fehler'; api.schalt_meldung = meldung(lauf('Empfang schalten') || lauf('Empfang ausschalten') || lauf('Workflow veröffentlichen')); }
}
// Nachprüfung M173b S1: Workflow beim Entfernen weder gefunden noch sicher weg (nicht 200/404): abbrechen, nichts gelöscht, normale Fehlermeldung
const wfAnsehen = lauf('Workflow ansehen (Entfernen)');
if (F.aktion === 'platz_freigeben' && V.weg === 'eigen' && wfAnsehen && ![200, 404].includes(wfAnsehen.statusCode)) {
  api.schalt_status = 'fehler';
  api.schalt_meldung = 'Der Workflow „MAIL Postfach Nr. ' + V.platz + '“ war nicht erreichbar (' + fehlerText(wfAnsehen) + '). Es wurde nichts gelöscht, bitte später erneut versuchen.';
}
// Migration 173 (Schritt P, P3): neues Postfach mit eigenem Workflow (api.anlegen: IDs der angelegten Teile; fehlt ein Teil, welche Teile wieder gelöscht sind)
// und Entfernen eines eigenen Postfachs (api.loeschen: Workflow und Zugangsdaten gelöscht bzw. noch da). Nie ein Passwort.
const idAus = r => r && r.statusCode === 200 && r.body && /^[A-Za-z0-9]{8,40}$/.test(String(r.body.id || '')) ? String(r.body.id) : '';
const neuesPf = F.aktion === 'zugang_speichern' && V.anlegen === true;
if (neuesPf) {
  const vb = lauf('Vorlage bauen') || {};
  const an = { imap_id: idAus(lauf('IMAP anlegen')), smtp_id: idAus(lauf('SMTP anlegen')), wf_id: idAus(lauf('Workflow anlegen')) };
  an.fertig = vb.ok === true && an.wf_id ? 'ja' : 'nein';
  if (an.fertig !== 'ja') {
    const LL = $('Abbruch-Liste').isExecuted ? $('Abbruch-Liste').all().map(x => x.json || {}) : [];
    const DD = $('Teil löschen (Abbruch)').isExecuted ? $('Teil löschen (Abbruch)').all().map(x => x.json || {}) : [];
    LL.forEach((t, i) => { if (t.teil) an[t.teil + '_weg'] = [200, 404].includes((DD[i] || {}).statusCode) ? 'ja' : 'nein'; });
    const erst = [['IMAP anlegen', 'Lesen'], ['SMTP anlegen', 'Versand'], ['Workflow anlegen', 'Workflow']].find(([n]) => { const r = lauf(n); return r && !idAus(r); });
    an.meldung = erst ? erst[1] + ': ' + fehlerText(lauf(erst[0])) : 'unbekannter Fehler';
  }
  api.anlegen = an;
}
if (F.aktion === 'platz_freigeben' && V.weg === 'eigen' && (lauf('Workflow löschen') || lauf('Lesen-Zugang löschen'))) {
  // Nachprüfung M173 H2: hieß der Workflow nicht „MAIL Postfach Nr. n“, wurde er nicht angefasst (name falsch; 404 = schon weg)
  const st = r => r ? String(r.statusCode || (r.error ? 'fehler' : '')) : '';
  const wa = lauf('Workflow ansehen (Entfernen)') || {};
  api.patch_status = '200';
  api.loeschen = { wf_status: lauf('Workflow löschen') ? ((lauf('Workflow nachsehen (Entfernen)') || {}).statusCode === 404 ? '404' : 'noch da')
      : (wa.statusCode === 404 ? '404' : wa.statusCode === 200 ? 'name falsch' : 'noch da'), imap_status: st(lauf('Lesen-Zugang löschen')),
    smtp_status: lauf('Versand-Zugang löschen') ? st(lauf('Versand-Zugang löschen')) : '-' };
}
return [{ json: { token: F.token, aktion: F.aktion, platz: neuesPf ? V.platz : F.platz, daten: F.daten, vorher: JSON.stringify(V), api: JSON.stringify(api) } }];

// Zurück auf die Postfächer in den Einstellungen; Sitzung wie bei ALLY 8 behandeln
const SEITE = '/webhook/web';
const F = $('Formular prüfen').first().json;
// Stelle auf der Seite (Stefan 17.10.2026): Position, offene Bereiche und Formular aus der Adresse des Formulars wieder anhängen, damit die Seite nicht nach oben springt
const ZQ = $('Formular').first().json.query || {};
const stelle = ziel => { const y = String(ZQ.zy || ''), o = String(ZQ.zo || ''), f = String(ZQ.zf || ''), t = String(ZQ.zt || '');
  if (!/^[0-9]{1,6}$/.test(y)) return ziel;
  const z = ziel.split('#')[0], s = 'zy=' + y + (/^[0-9]{1,3}(\.[0-9]{1,3}){0,39}$/.test(o) ? '&zo=' + o : '') + (/^[A-Za-z0-9_-]{0,60}~[0-9]{1,3}$/.test(f) ? '&zf=' + f + (/^-?[0-9]{1,5}$/.test(t) ? '&zt=' + t : '') : '');
  return z + (z.includes('?') ? '&' : '?') + s; };
// Ergebnis kommt aus "Abschließen" (normaler Weg) oder aus "Vorbereiten" (nicht erlaubt)
const r = ($('Abschließen').isExecuted ? $('Abschließen').first().json.r : $('Vorbereiten').first().json.v) || {};
const keks = (wert, alter) => 'ally_sitzung=' + wert + '; Path=' + SEITE + '; Max-Age=' + alter + '; HttpOnly; Secure; SameSite=None';
let ziel, cookie = '';
if (F.aktion === 'ungueltig' || r.ungueltig) ziel = SEITE + '?m=ungueltig';
else if (r.angemeldet === false) { ziel = SEITE + '?m=abgelaufen'; cookie = keks('', 0); }
else { ziel = SEITE + '?ansicht=einstellungen&bereich=postfaecher'; ziel = stelle(ziel); if (F.token) cookie = keks(F.token, 2592000); }
return [{ json: { ziel, set_cookie: cookie } }];

// Migration 173 (Schritt P, P3; Bauplan „P-Zielmodell“, Koordinator 29.10.2026): feste Vorlage „MAIL Postfach Nr. n“ (Code-Knoten „Vorlage bauen“ in ALLY 9).
// Eingesetzt werden nur die Nummer (ganze Zahl ab 11, aus der Datenbank) und die IDs der eben angelegten Zugangsdaten (aus der Antwort der n8n-Schnittstelle),
// nie Text aus dem Formular. Ordner „Mail“, für MCP freigegeben (Stefan 29.10.), Einstellungen wie die Platz-Workflows: keine gespeicherten erfolgreichen Läufe,
// Fehler-Workflow EzIkvTvJHlrZa1Wd (Koordinator 29.10.). Aufrufen dürfen nur MAIL 4 (Aktionen), SHOPIFY 2 (Senden) und MAIL 6 (Empfang prüfen, seit 179).
// Migration 179 (P6, Empfang nach einer Störung selbst wiederherstellen): Aktion empfang_pruefen (direkt von MAIL 6, erfolgreiche Läufe werden hier nicht gespeichert): nächste UID des Posteingangs (UIDNEXT) und,
// wenn es eine höhere UID gibt als die zuletzt geholte Mail, die Zahl der ungelesenen Mails darüber (genau das, was der Auslöser holen würde). Nur lesen, nur Zahlen.
const V = $('Vorbereiten').first().json.v || {};
const lauf = n => $(n).isExecuted ? (($(n).first() || {}).json || {}) : {};
const idAus = r => r.statusCode === 200 && r.body && /^[A-Za-z0-9]{8,40}$/.test(String(r.body.id || '')) ? String(r.body.id) : '';
const imap = idAus(lauf('IMAP anlegen')), smtp = idAus(lauf('SMTP anlegen'));
const N = Number(V.platz);
if (V.anlegen !== true || !Number.isInteger(N) || N < 11 || !imap || !smtp) return [{ json: { ok: false, imap_id: imap, smtp_id: smtp } }];
