const ORDNER_MAIL_WERT = '__ALLY_N8N_ORDNER_POSTFAECHER__', ORDNER_MAIL = /^[A-Za-z0-9]{8,40}$/.test(ORDNER_MAIL_WERT) ? ORDNER_MAIL_WERT : '';
