const K = (k, name, type, typeVersion, position, parameters, extra) => Object.assign({ id: 'postfach-' + N + '-' + k, name, type, typeVersion, position, parameters }, extra || {});
const PRUEF = '// Fest: Postfach Nr. ' + N + '. Aufträge nur für genau diese Nummer (MAIL 4: verschieben, markieren, Entwurf, Ordner lesen; SHOPIFY 2: senden; MAIL 6: Empfang prüfen).\n'
  + 'const NR = ' + N + ';\n' + String.raw`const AKT = ['verschieben', 'markieren', 'entwurf', 'ordner_lesen', 'senden', 'empfang_pruefen'];
const L = $input.all();
if (!L.length) throw new Error('Kein Auftrag. Nichts ausgeführt.');
for (const it of L) {
  const a = it.json || {};
  if (Number(a.nr) !== NR) throw new Error('Der Auftrag gehört nicht zu Postfach Nr. ' + NR + '. Nichts ausgeführt.');
  if (!AKT.includes(a.aktion) || a.aktion !== L[0].json.aktion) throw new Error('Unbekannte oder gemischte Postfach-Aktion. Nichts ausgeführt.');
  if (a.aktion === 'senden' && (!/^[^\s@<>"',;]{1,64}@[^\s@<>"',;]{1,190}$/.test(String(a.an || '')) || !String(a.von || ''))) throw new Error('Empfänger oder Absender fehlt. Nichts gesendet.');
  if (a.aktion === 'empfang_pruefen' && !/^[0-9]{1,12}$/.test(String(a.uid ?? ''))) throw new Error('Die zuletzt geholte Mail-Nummer fehlt. Nichts geprüft.');
