const INBOX = { __rl: true, value: 'INBOX', mode: 'path' };
const EINGANG = String.raw`// Migration 179 (P6): nur der Posteingang – nächste UID (UIDNEXT). Kandidat für eine Lücke, wenn es eine höhere UID gibt als die zuletzt geholte Mail.
// Nicht prüfbar (P6b, 30.10.2026): scheitert die Abfrage (z. B. Zeitüberschreitung, Server nicht erreichbar) oder liefert der Server kein UIDNEXT, wird nichts geworfen
// (kein Fehler, kein SYS 7) – Ergebnis „nicht prüfbar“ mit Grund; MAIL 6 überspringt das Postfach still. Der Empfang über den Auslöser bleibt unberührt.
const a = $('Auftrag prüfen').first().json;
