const ERGEBNIS = String.raw`// Migration 179 (P6): nur Zahlen – ungelesene Mails mit höherer UID als die zuletzt geholte (die der Auslöser holen würde), ohne Inhalt
// P6b: nicht prüfbar (siehe „Empfang: Posteingang“, auch wenn die Suche scheitert) ohne Zahlen, mit Grund – MAIL 6 überspringt das Postfach still
