const U = $('Empfang: Ungelesene').isExecuted ? $('Empfang: Ungelesene').all().map(i => i.json || {}) : [];
const f = U.find(m => m.error);
if (f) return nicht('Suche gescheitert: ' + (typeof f.error === 'string' ? f.error : String(f.error.message || JSON.stringify(f.error))).slice(0, 200));
